command:
set -euo pipefail
LIVE=/home/ai-core-node/.claude/star/visual/buehne.html
REPO=/home/ai-core-node/clay-global-research-entity
SRC_COMMIT=108c369c52b0e7b10ce1c6f4571381995f62a60f
TMP=$(mktemp -d /tmp/avatar-microexpr-live.XXXXXX)
trap 'rm -rf "$TMP"' EXIT
echo HOST=$(hostname)
echo SERVICE_BEFORE=$(systemctl --user is-active frankenstein-buehne.service)
COUNT=$(DISPLAY=:0 xdotool search --name '^FranKenstein -- live$' 2>/dev/null | wc -l)
echo WINDOW_COUNT_BEFORE=$COUNT
[ "$COUNT" -eq 1 ] || { echo SINGLETON_REFUSED; exit 60; }
echo WINDOW_BEFORE=$(DISPLAY=:0 xdotool search --name '^FranKenstein -- live$' | head -1)
DISPLAY=:0 wmctrl -lxG 2>/dev/null | grep -F 'FranKenstein -- live' || true
AVAIL_KB=$(awk '/MemAvailable:/ {print $2}' /proc/meminfo)
CPUS=$(nproc)
LOAD1=$(awk '{print $1}' /proc/loadavg)
echo HOST_ADMISSION mem_available_kb=$AVAIL_KB cpus=$CPUS load1=$LOAD1
[ "$AVAIL_KB" -ge 1048576 ] || { echo HOST_MEMORY_REFUSED; exit 61; }
echo LIVE_SHA_BEFORE=$(sha256sum "$LIVE" | awk '{print $1}')
[ -d "$REPO/.git" ] || { echo REPO_MISSING; exit 62; }
git -C "$REPO" fetch -q origin "$SRC_COMMIT"
git -C "$REPO" show FETCH_HEAD:research_entity/coordination/apply_avatar_microexpr_v1.py > "$TMP/apply_avatar_microexpr_v1.py"
git -C "$REPO" show FETCH_HEAD:research_entity/coordination/avatar_microexpr_v1.js > "$TMP/avatar_microexpr_v1.js"
echo APPLY_BLOB=$(git -C "$REPO" rev-parse FETCH_HEAD:research_entity/coordination/apply_avatar_microexpr_v1.py)
echo ENGINE_BLOB=$(git -C "$REPO" rev-parse FETCH_HEAD:research_entity/coordination/avatar_microexpr_v1.js)
node --check "$TMP/avatar_microexpr_v1.js"
python3 "$TMP/apply_avatar_microexpr_v1.py"
sleep 5
echo SERVICE_AFTER=$(systemctl --user is-active frankenstein-buehne.service)
COUNT2=$(DISPLAY=:0 xdotool search --name '^FranKenstein -- live$' 2>/dev/null | wc -l)
echo WINDOW_COUNT_AFTER=$COUNT2
[ "$COUNT2" -eq 1 ] || { echo POST_SINGLETON_FAIL; exit 63; }
DISPLAY=:0 wmctrl -lxG 2>/dev/null | grep -F 'FranKenstein -- live' || true
echo HTTP=$(curl -fsS -o /dev/null -w '%{http_code}' http://127.0.0.1:8788/)
echo HTTP_MARKER=$(curl -fsS http://127.0.0.1:8788/ | grep -c 'FRANK_MICROEXPR_V1 BEGIN')
echo LIVE_SHA_AFTER=$(sha256sum "$LIVE" | awk '{print $1}')
grep -q 'FRANK_MICROEXPR_V1 BEGIN' "$LIVE"
grep -q '_mikroMimikSchritt(t);' "$LIVE"
grep -q '_mikroMimikStateAktualisieren(b);' "$LIVE"
echo DELIVERY_REPAIR_APPLY_PASS
